-- RegWay AI conversations (roadmap Priority order item 4): saved chats a
-- user can resume. Messages were a flat per-firm log that nothing read
-- back; they now belong to a conversation, and regway-ai-chat sends the
-- conversation's earlier turns to the model so follow-ups have context.
--
-- A conversation is personal: its creator's, within their firm. `context`
-- keeps the fund / company / regulation scope it was started from, so a
-- resumed chat stays about the same thing. The id is generated by the
-- client (one per new chat) and the row created on its first message.
-- Messages from before this migration have no conversation and aren't listed.

create table regway_ai_conversations (
  id uuid primary key,
  firm_id uuid not null references firms(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  title text not null,
  context jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- The history list: a user's conversations, most recent first.
create index regway_ai_conversations_user_updated_idx on regway_ai_conversations (user_id, updated_at desc);
create index regway_ai_conversations_firm_idx on regway_ai_conversations (firm_id);

alter table regway_ai_conversations enable row level security;

create policy "users manage own ai conversations" on regway_ai_conversations
  for all
  using (user_id = (select auth.uid()) and firm_id = (select auth_firm_id()))
  with check (user_id = (select auth.uid()) and firm_id = (select auth_firm_id()));

alter table regway_ai_messages
  add column conversation_id uuid references regway_ai_conversations(id) on delete cascade;

-- Loading one conversation's turns in order.
create index regway_ai_messages_conversation_idx on regway_ai_messages (conversation_id, created_at);
